#!/bin/bash
# Task 084-w11-accept-cyclone-29 -- meshsim v1.25 acceptance kit (WORKER11, branch v1.25-meshsim). The kit (meshsim.jar, Java 17 bytecode;
# the prebuilt replay controller; the universal replayer tables; run_shard.sh, calibrate.sh) is embedded below as a base64
# tgz, SHA-256 checked. Runs: ./run_shard.sh -d /tmp/w9-deliveries -p cyclone-29 -M /tmp/w9-deliveries/cyclone-29.manifest.json -f 0 -n 8192 -j 16 -x 64 -m f8a0622e144a944c51386b5b36f81101dcdeb16e5a8d950c1e9ca0e3097f8982 $RES/cyclone-29
# Commits only results (CSV, summaries, logs); deliveries are generated into scratch and deleted (DECISIONS-v1.25 s7).
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/084-w11-accept-cyclone-29; mkdir -p "$RES"
WANT=9a1acd8895705d04a120645773dcd068613cdc0ecb2ea46d12d20937379a72cd
W=/tmp/w11-084-w11-accept-cyclone-29; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
cd "$W/w11-kit" || exit 2
sha256sum -c --quiet HASHES || { echo "kit files differ from HASHES"; exit 2; }
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1; free -g | head -2
./run_shard.sh -d /tmp/w9-deliveries -p cyclone-29 -M /tmp/w9-deliveries/cyclone-29.manifest.json -f 0 -n 8192 -j 16 -x 64 -m f8a0622e144a944c51386b5b36f81101dcdeb16e5a8d950c1e9ca0e3097f8982 $RES/cyclone-29; RC=$?
echo "exit $RC at $(date -u)"
rm -rf "$W"
exit $RC
